from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import WebhookFilterConfig

class ModifyWebhookFilterView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def patch(self, request, filter_id):
        try:
            config = WebhookFilterConfig.objects.get(
                id=filter_id,
                webhook__created_by=request.user
            )
        except WebhookFilterConfig.DoesNotExist:
            return Response({'error': 'Filter not found or unauthorized'}, status=status.HTTP_404_NOT_FOUND)

        event_types = request.data.get('event_types')
        if event_types is not None:
            config.subscribed_event_types = event_types
            config.save(update_fields=['subscribed_event_types'])
        return Response({'id': config.id, 'subscribed_event_types': config.subscribed_event_types})
